'use strict';

function buildSiteMap(brand, entries, width) {
  if (typeof brand !== 'string' || brand.trim() === '') {
    throw new TypeError('brand must be a non-empty string');
  }
  if (!Array.isArray(entries)) {
    throw new TypeError('entries must be an array');
  }
  if (typeof width !== 'number' || !Number.isFinite(width) || width < 0) {
    throw new TypeError('width must be a finite non-negative number');
  }

  const links = entries.map((entry) => {
    if (entry === null || typeof entry !== 'object') {
      throw new TypeError('each entry must be an object');
    }
    if (typeof entry.label !== 'string' || entry.label.trim() === '' ||
        typeof entry.target !== 'string' || entry.target.trim() === '') {
      throw new TypeError('entry fields must be non-empty strings');
    }
    return {
      label: entry.label.trim(),
      target: entry.target.trim()
    };
  });

  return {
    brand: brand.trim(),
    direction: width <= 640 ? 'column' : 'row',
    links
  };
}

module.exports = { buildSiteMap };

