'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['buildSiteMap']);
assert.strictEqual(typeof api.buildSiteMap, 'function');
const { buildSiteMap } = api;

const entries = [
  { label: '  Home  ', target: ' /home ' },
  { label: 'Docs', target: '/docs' },
  { label: 'Docs', target: '/docs' }
];
const original = JSON.parse(JSON.stringify(entries));
const result = buildSiteMap('  Acme  ', entries, 640);
assert.deepStrictEqual(result, {
  brand: 'Acme',
  direction: 'row',
  links: [
    { label: 'Home', target: '/home' },
    { label: 'Docs', target: '/docs' },
    { label: 'Docs', target: '/docs' }
  ]
});
assert.deepStrictEqual(entries, original);
assert.notStrictEqual(result.links, entries);
for (let i = 0; i < entries.length; i += 1) {
  assert.notStrictEqual(result.links[i], entries[i]);
}

entries[0].label = 'Changed';
entries[1].target = '/changed';
entries.push({ label: 'More', target: '/more' });
assert.deepStrictEqual(result.links, [
  { label: 'Home', target: '/home' },
  { label: 'Docs', target: '/docs' },
  { label: 'Docs', target: '/docs' }
]);

assert.deepStrictEqual(buildSiteMap('B', [], 0), {
  brand: 'B', direction: 'column', links: []
});
assert.strictEqual(buildSiteMap('B', [], 639.999).direction, 'column');
assert.strictEqual(buildSiteMap('B', [], 640).direction, 'row');

for (const badBrand of [null, undefined, 1, {}, '', '   ']) {
  assert.throws(() => buildSiteMap(badBrand, [], 800), TypeError);
}
for (const badEntries of [null, {}, 'x', 1]) {
  assert.throws(() => buildSiteMap('B', badEntries, 800), TypeError);
}
for (const badEntry of [null, [], 1, 'x', {}, { label: 'x' }, { target: 'x' },
  { label: '', target: 'x' }, { label: '  ', target: 'x' },
  { label: 'x', target: '' }, { label: 'x', target: '  ' },
  { label: 1, target: 'x' }, { label: 'x', target: 1 }]) {
  assert.throws(() => buildSiteMap('B', [badEntry], 800), TypeError);
}
for (const badWidth of [NaN, Infinity, -Infinity, -1, '640', null]) {
  assert.throws(() => buildSiteMap('B', [], badWidth), TypeError);
}

